import { Address } from "@openzeppelin/contracts/utils/Address.sol";
import './CallbackValidation.sol';
import './PoolAddress.sol';
import './TransferHelper.sol';
import '../interfaces/IEnosysDexV3Factory.sol';
import '../interfaces/external/IWNat.sol';
import "../NonfungiblePositionManager.sol";
import './PositionKey.sol';
import './FullMath.sol';
import './FixedPoint128.sol';

/// @title Nonfungible Position ManagerHelper Library 
/// @dev This library is used to store NPS code externally to save bytecode size
library NonfungiblePositionManagerHelper {

    struct MintCallbackData {
        PoolAddress.PoolKey poolKey;
        address payer;
    }

    function updatePositionOnLiquidityIncrease(NonfungiblePositionManager.Position storage position, IEnosysDexV3Pool pool, uint128 liquidityAdd) public {
        bytes32 positionKey = PositionKey.compute(address(this), position.tickLower, position.tickUpper);

        // this is now updated to the current transaction
        (, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128, , , , ) = pool.positions(positionKey);

        position.tokensOwed0 += uint128(
            FullMath.mulDiv(
                feeGrowthInside0LastX128 - position.feeGrowthInside0LastX128,
                position.liquidity,
                FixedPoint128.Q128
            )
        );
        position.tokensOwed1 += uint128(
            FullMath.mulDiv(
                feeGrowthInside1LastX128 - position.feeGrowthInside1LastX128,
                position.liquidity,
                FixedPoint128.Q128
            )
        );

        position.feeGrowthInside0LastX128 = feeGrowthInside0LastX128;
        position.feeGrowthInside1LastX128 = feeGrowthInside1LastX128;
        position.liquidity += liquidityAdd;
    }

    function updatePositionOnLiquidityDecrease(NonfungiblePositionManager.Position storage position, IEnosysDexV3Pool pool, uint128 liquiditySub, uint256 amount0, uint256 amount1) public {
        uint128 positionLiquidity = position.liquidity;
        bytes32 positionKey = PositionKey.compute(address(this), position.tickLower, position.tickUpper);
        // this is now updated to the current transaction
        (, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128, , , ,  ) = pool.positions(positionKey);

        position.tokensOwed0 +=
            uint128(amount0) +
            uint128(
                FullMath.mulDiv(
                    feeGrowthInside0LastX128 - position.feeGrowthInside0LastX128,
                    positionLiquidity,
                    FixedPoint128.Q128
                )
            );
        position.tokensOwed1 +=
            uint128(amount1) +
            uint128(
                FullMath.mulDiv(
                    feeGrowthInside1LastX128 - position.feeGrowthInside1LastX128,
                    positionLiquidity,
                    FixedPoint128.Q128
                )
            );

        position.feeGrowthInside0LastX128 = feeGrowthInside0LastX128;
        position.feeGrowthInside1LastX128 = feeGrowthInside1LastX128;
        // subtraction is safe because we checked positionLiquidity is gte params.liquidity
        position.liquidity = positionLiquidity - liquiditySub;
    }

    function validateNewTokenDescriptor(address factory, address currentDescriptor, address newDescriptor) external view {
        require(msg.sender == IEnosysDexV3Factory(factory).owner(), 'Not allowed');
        require(Address.isContract(newDescriptor), 'Not a contract');
        require(newDescriptor != currentDescriptor, 'The same address');
    }

    /// @notice Called to `msg.sender` after minting liquidity to a position from IEnosysDexV3Pool#mint.
    /// @dev In the implementation you must pay the pool tokens owed for the minted liquidity.
    /// The caller of this method must be checked to be a EnosysDexV3Pool deployed by the canonical EnosysDexV3Factory.
    /// @param factory The address of the EnosysDexV3Factory that deployed the pool
    /// @param poolInitCodeHash The init code hash of the pool
    /// @param wnat The address of the WNat token
    /// @param amount0Owed The amount of token0 due to the pool for the minted liquidity
    /// @param amount1Owed The amount of token1 due to the pool for the minted liquidity
    /// @param data Any data passed through by the caller via the IEnosysDexV3PoolActions#mint call
    function enosysdexV3MintCallback(
        address factory,
        bytes32 poolInitCodeHash,
        address wnat,
        uint256 amount0Owed,
        uint256 amount1Owed,
        bytes calldata data
    ) external {
        MintCallbackData memory decoded = abi.decode(data, (MintCallbackData));
        CallbackValidation.verifyCallback(factory, poolInitCodeHash, decoded.poolKey);

        if (amount0Owed > 0) pay(wnat, decoded.poolKey.token0, decoded.payer, msg.sender, amount0Owed);
        if (amount1Owed > 0) pay(wnat, decoded.poolKey.token1, decoded.payer, msg.sender, amount1Owed);
    }

    /// @dev the implementation is taken from PeripheryPayments
    /// @param wnat The address of the WNat token
    /// @param token The token to pay
    /// @param payer The entity that must pay
    /// @param recipient The entity that will receive payment
    /// @param value The amount to pay
    function pay(
        address wnat,
        address token,
        address payer,
        address recipient,
        uint256 value
    ) internal {
        if (token == wnat && address(this).balance >= value) {
            // pay with WNat
            IWNat(wnat).deposit{value: value}(); // wrap only what is needed to pay
            IWNat(wnat).transfer(recipient, value);
        } else if (payer == address(this)) {
            // pay with tokens already in the contract (for the exact input multihop case)
            TransferHelper.safeTransfer(token, recipient, value);
        } else {
            // pull payment
            TransferHelper.safeTransferFrom(token, payer, recipient, value);
        }
    }
}

