// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;

import '../interfaces/IEnosysDexV3Pool.sol';
import './PoolAddress.sol';

/// @notice Provides validation for callbacks from EnosysDex V3 Pools
library CallbackValidation {
    /// @notice Returns the address of a valid EnosysDex V3 Pool
    /// @param factory The contract address of the EnosysDex V3 factory
    /// @param tokenA The contract address of either token0 or token1
    /// @param tokenB The contract address of the other token
    /// @param fee The fee collected upon every swap in the pool, denominated in hundredths of a bip
    /// @return pool The V3 pool contract address
    function verifyCallback(
        address factory,
        bytes32 poolInitCodeHash,
        address tokenA,
        address tokenB,
        uint24 fee
    ) internal view returns (IEnosysDexV3Pool pool) {
        return verifyCallback(factory, poolInitCodeHash, PoolAddress.getPoolKey(tokenA, tokenB, fee));
    }

    /// @notice Returns the address of a valid EnosysDex V3 Pool
    /// @param factory The contract address of the EnosysDex V3 factory
    /// @param poolKey The identifying key of the V3 pool
    /// @return pool The V3 pool contract address
    function verifyCallback(address factory, bytes32 poolInitCodeHash, PoolAddress.PoolKey memory poolKey)
        internal
        view
        returns (IEnosysDexV3Pool pool)
    {
        pool = IEnosysDexV3Pool(PoolAddress.computeAddress(factory, poolInitCodeHash, poolKey));
        require(msg.sender == address(pool));
    }
}

